": 124}, {\"x\": 5030, \"y\": 236, \"w\": 80, \"h\": 184}, {\"x\": 5111, \"y\": 168, \"w\": 77, \"h\": 252}, {\"x\": 5188, \"y\": 108, \"w\": 74, \"h\": 312}, {\"x\": 5263, \"y\": 68, \"w\": 90, \"h\": 352}, {\"x\": 5428, \"y\": 370, \"w\": 70, \"h\": 50}, {\"x\": 5498, \"y\": 312, \"w\": 45, \"h\": 108}, {\"x\": 5544, \"y\": 266, \"w\": 127, \"h\": 154}, {\"x\": 5671, \"y\": 311, \"w\": 59, \"h\": 109}, {\"x\": 5731, \"y\": 370, \"w\": 88, \"h\": 50}];\n\n// ── LEVEL 2 DATA ────────────────────────────────────────────────\nconst FOREST_BG_SRC    = \"data:image/jpeg;base64,\";\nconst WOLF_SHEET_SRC   = \"data:image/png;base64,\";\nconst FOREST_STAGE_SRC = \"data:image/png;base64,\";\nconst LEVEL_W2  = 6000;\nconst STAGE_H2  = 370;\nconst BG_W2     = 1200;\n\n// Wolf sprite sheet layout: 4 cols × 3 rows, each frame ~160×285\nconst WF = {\n  FW: 160, FH: 285,\n  walk:   [{x:0,y:0},{x:160,y:0},{x:320,y:0},{x:480,y:0}],\n  attack: [{x:0,y:285}],\n  angry:  [{x:0,y:285}],\n  dead:   [{x:480,y:570}]\n};\n\n// Level 2 raw platforms (forest terrain coordinates)\nconst RAW_PLATS_L2 = [\n  {x:0,   y:368, w:163},\n  {x:176, y:258, w:359},\n  {x:623, y:328, w:109},\n  {x:745, y:323, w:326},\n  {x:1084,y:266, w:285},\n  {x:1382,y:271, w:169},\n  {x:1578,y:319, w:48},\n  {x:1660,y:293, w:190},\n  {x:1863,y:293, w:45},\n  {x:1917,y:255, w:48},\n  {x:2012,y:207, w:88},\n  {x:2174,y:207, w:89},\n  {x:2323,y:270, w:89},\n  {x:2452,y:220, w:48},\n  {x:2574,y:212, w:88},\n  {x:2723,y:254, w:109},\n  {x:2845,y:147, w:319},\n  {x:3197,y:291, w:89},\n  {x:3299,y:364, w:48},\n  {x:3367,y:363, w:81},\n  {x:3462,y:365, w:101},\n  {x:3577,y:138, w:582},\n  {x:4173,y:132, w:352},\n  {x:4559,y:282, w:48},\n  {x:4620,y:365, w:68},\n  {x:4708,y:370, w:115},\n  {x:4837,y:370, w:45},\n  {x:4877,y:327, w:122},\n  {x:5013,y:186, w:108},\n  {x:5142,y:127, w:169},\n  {x:5412,y:247, w:502},\n  {x:5934,y:303, w:61},\n];\n// Moving platforms for L2: {x, baseY=top position, w, h, range=px down, period=frames full cycle}\n// ─── Level 3 (Città) ──────────────────────────────────────────────────\nconst CITY_BG_SRC=\"data:image/png;base64,\";\nconst CITY_STAGE_SRC=\"data:image/png;base64,\";\nconst CACCA_SRC=\"data:image/png;base64,\";\nconst SALI_SRC=\"data:image/png;base64,\";\nconst MUSIC_CITY_SRC=\"data:audio/mpeg;base64,\";\nconst LEVEL_W3=7277,STAGE_H3=420,BG_W3=688;\nconst RAW_PLATS_L3=[\n  {x:0,y:382,w:440},{x:505,y:326,w:75},{x:580,y:290,w:70},{x:655,y:255,w:225},\n  {x:1000,y:251,w:85},{x:1115,y:336,w:115},{x:1230,y:376,w:405},{x:1635,y:385,w:280},\n  {x:1920,y:326,w:255},{x:2190,y:246,w:260},{x:2455,y:182,w:260},{x:2750,y:243,w:260},\n  {x:3025,y:336,w:260},{x:3310,y:226,w:90},{x:3415,y:292,w:95},{x:3650,y:376,w:270},\n  {x:3920,y:333,w:80},{x:4150,y:376,w:315},{x:4640,y:268,w:120},{x:4905,y:340,w:260},\n  {x:5200,y:299,w:260},{x:5495,y:263,w:70},{x:5640,y:324,w:70},{x:5755,y:374,w:430},\n  {x:6185,y:238,w:65},{x:6255,y:183,w:90},{x:6345,y:120,w:115},{x:6460,y:85,w:140},\n  {x:6760,y:346,w:65},{x:6895,y:233,w:185},{x:7205,y:357,w:75},\n];\nconst CACCA_FW=224,CACCA_FH1=390,CACCA_FH2=380,CACCA_FH3=426;\nconst CACCA_FRAMES={\n  walk:[{x:0,y:0},{x:224,y:0},{x:448,y:0},{x:672,y:0}],\n  attack:[{x:0,y:770}],          // punch stance in row 3\n  dead:[{x:672,y:770}]           // lying dead in row 3\n};\nconst MOVING_SALI_L3=[\n  {id:'s1',x:1728,baseY:389,w:157,h:22,range:80,period:200,phase:0,  y:389,prevY:389},\n  {id:'s2',x:1990,baseY:332,w:157,h:22,range:80,period:200,phase:50, y:332,prevY:332},\n  {id:'s3',x:2529,baseY:182,w:157,h:22,range:80,period:200,phase:25, y:182,prevY:182},\n  {id:'s4',x:2262,baseY:250,w:157,h:22,range:80,period:200,phase:75, y:250,prevY:250},\n  {id:'s5',x:2823,baseY:246,w:157,h:22,range:80,period:200,phase:100,y:246,prevY:246},\n  {id:'s6',x:3097,baseY:339,w:157,h:22,range:80,period:200,phase:30, y:339,prevY:339},\n  {id:'s7',x:4638,baseY:272,w:119,h:22,range:80,period:200,phase:60, y:272,prevY:272},\n  {id:'s8',x:4979,baseY:341,w:157,h:22,range:80,period:200,phase:90, y:341,prevY:341},\n  {id:'s9',x:5273,baseY:302,w:157,h:22,range:80,period:200,phase:120,y:302,prevY:302},\n  {id:'s10',x:6897,baseY:235,w:180,h:22,range:80,period:200,phase:150,y:235,prevY:235},\n];\nconst MOVING_PLATS_L2=[\n  {id:'mp1',x:5311,baseY:80,w:101,h:20,range:300,period:480,phase:0,y:80}\n];\n\n\n\nconst PW=44, PH=72;\n\nfunction buildPlatforms(){\n  const list=RAW_PLATS.map(p=>({...p,h:H-p.y,type:\"solid\"}));\n  const lastP=[...RAW_PLATS].sort((a,b)=>b.x-a.x)[0];\n  list.push({x:lastP.x,y:lastP.y-24,w:lastP.w,h:24,type:\"goal\"});\n  return list;\n}\nfunction placeDonuts(platforms){\n  const types=[\"plain\",\"choco\",\"pink\",\"sugar\"],list=[];let id=0;\n  for(const p of platforms){\n    if(p.type===\"goal\"||p.w<28)continue;\n    const n=Math.max(1,Math.floor(p.w/110));\n    for(let i=0;i<n;i++){\n      if(rnd(1)>0.55)continue;\n      list.push({id:id++,x:p.x+p.w*(i+1)/(n+1),y:p.y-28,\n        type:types[Math.floor(rnd(types.length))],collected:false,bob:rnd(Math.PI*2)});\n    }\n  }\n  return list;\n}\nfunction placeEnemies(platforms){\n  const list=[];let id=0;\n  const wide=platforms.filter(p=>p.type===\"solid\"&&p.w>=80);\n  for(let i=2;i<wide.length;i+=2){\n    const p=wide[i];\n    list.push({id:id++,x:p.x+p.w*0.35,y:p.y-PH,\n      w:40,h:PH,vx:0.8+rnd(0.5),sx:p.x+5,range:p.w-10,\n      frame:0,state:\"walk\",hitTimer:0});\n  }\n  return list;\n}\n\n\n// ─── Settings ────────────────────────────────────────────────────\nlet optLives=3, optDiff='low';\nlet optMusicVol=0.22, optSfxVol=0.80;\n\n// ─── Canvas ──────────────────────────────────────────────────────\nconst cvs=document.getElementById('cvs');\nconst ctx=cvs.getContext('2d');\nlet SX=1,SY=1;\nfunction resize(){\n  const r=cvs.getBoundingClientRect();\n  cvs.width=r.width||window.innerWidth;\n  cvs.height=r.height||window.innerHeight;\n  SX=cvs.width/W; SY=cvs.height/H;\n}\nresize(); window.addEventListener('resize',resize);\n\n// ─── Input ───────────────────────────────────────────────────────\nlet K={ArrowLeft:false,ArrowRight:false,ArrowUp:false};\ndocument.addEventListener('keydown',e=>{\n  if(e.key==='ArrowLeft' ||e.key==='a') K.ArrowLeft=true;\n  if(e.key==='ArrowRight'||e.key==='d') K.ArrowRight=true;\n  if(e.key==='ArrowUp'   ||e.key==='w'||e.key===' ') K.ArrowUp=true;\n  if(e.key===' ')e.preventDefault();\n});\ndocument.addEventListener('keyup',e=>{\n  if(e.key==='ArrowLeft' ||e.key==='a') K.ArrowLeft=false;\n  if(e.key==='ArrowRight'||e.key==='d') K.ArrowRight=false;\n  if(e.key==='ArrowUp'   ||e.key==='w'||e.key===' ') K.ArrowUp=false;\n});\n\n// ─── Music ───────────────────────────────────────────────────────\nconst audIntro = document.getElementById('aud-intro');\nconst audGame  = document.getElementById('aud-game');\nlet musicStarted = false;\n\nfunction playIntro(){\n  audGame.pause(); audGame.currentTime=0;\n  audIntro.volume=optMusicVol;\n  audIntro.play().catch(()=>{});\n}\nfunction playGame(){\n  audIntro.pause(); audIntro.currentTime=0;\n  audGame.volume=optMusicVol;\n  audGame.play().catch(()=>{});\n}\nfunction playForest(){\n  audIntro.pause(); audIntro.currentTime=0;\n  audGame.pause();  audGame.currentTime=0;\n  if(currentLevel===3){audCity.volume=optMusicVol;audCity.play().catch(()=>{});return;}\n  audForest.volume=optMusicVol;audForest.play().catch(()=>{});\n}\nfunction stopAll(){\n  audIntro.pause(); audIntro.currentTime=0;\n  audGame.pause();  audGame.currentTime=0;\n  audForest.pause(); audForest.currentTime=0;\n  audCity.pause();  audCity.currentTime=0;\n}\n// Unlock audio on first tap (required by browsers/WebView)\nfunction unlockAudio(){\n  if(musicStarted)return;\n  musicStarted=true;\n  // Briefly play+pause both to unlock them\n  audIntro.play().then(()=>{ if(screen!=='menu'&&screen!=='splash')audIntro.pause(); }).catch(()=>{});\n}\ndocument.addEventListener('pointerdown',unlockAudio,{once:true});\ndocument.addEventListener('click',unlockAudio,{once:true});\n\n// ─── SFX ─────────────────────────────────────────────────────────\nlet actx=null;\nfunction getAC(){if(!actx){try{actx=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(actx&&actx.state==='suspended')actx.resume();return actx;}\nfunction tone(f,tp,dur,vol=0.2,d=0){\n  try{const c=getAC();if(!c)return;\n  const o=c.createOscillator(),g=c.createGain();\n  o.connect(g);g.connect(c.destination);o.type=tp;\n  o.frequency.setValueAtTime(f,c.currentTime+d);\n  g.gain.setValueAtTime(0,c.currentTime+d);\n  g.gain.linearRampToValueAtTime(vol*optSfxVol,c.currentTime+d+0.01);\n  g.gain.exponentialRampToValueAtTime(0.001,c.currentTime+d+dur);\n  o.start(c.currentTime+d);o.stop(c.currentTime+d+dur+0.05);}catch(e){}\n}\nconst sfxJump =()=>{tone(500,'sine',0.14,0.22);tone(680,'sine',0.1,0.16,0.06);};\nconst sfxDonut=()=>{tone(880,'sine',0.06,0.2);tone(1100,'sine',0.06,0.18,0.07);tone(1320,'sine',0.1,0.18,0.13);};\nconst sfxStomp=()=>{tone(160,'square',0.16,0.3);tone(100,'square',0.18,0.25,0.05);};\nconst sfxHurt =()=>{tone(200,'sawtooth',0.22,0.28);tone(140,'sawtooth',0.18,0.22,0.09);};\nconst sfxStep =fr=>{if(fr%20===0)tone(110,'sine',0.04,0.04);};\n\n// ─── HUD ─────────────────────────────────────────────────────────\nlet lives=3,donutCount=0,score=0;\nfunction updateHUD(){\n  document.getElementById('hud-lives').textContent='❤️ '+lives;\n  document.getElementById('hud-donuts').textContent='🍩 '+donutCount;\n  document.getElementById('hud-score').textContent='⭐ '+score;\n}\n\n// ─── Screen routing ──────────────────────────────────────────────\nlet screen='splash', sRef=null, raf=null, menuRaf=null;\n\nfunction showMenu(){\n  screen='menu';\n  document.getElementById('menu').style.display   ='flex';\n  document.getElementById('opts').style.display   ='none';\n  document.getElementById('overlay').style.display='none';\n  document.getElementById('hud').style.display    ='none';\n  document.getElementById('controls').style.display='none';\n  playIntro();\n  startMenuAnim();\n}\nfunction showOpts(){\n  document.getElementById('menu').style.display='none';\n  document.getElementById('opts').style.display='flex';\n  // music keeps playing (intro)\n}\nfunction showEndScreen(type,opts={}){\n  screen=type;\n  document.getElementById('overlay').style.display='flex';\n  document.getElementById('hud').style.display    ='none';\n  document.getElementById('controls').style.display='none';\n  stopAll();\n  if(type==='win'){\n    document.getElementById('ov-icon').textContent ='🏰';\n    document.getElementById('ov-title').textContent='Castello raggiunto!';\n    document.getElementById('ov-sub').textContent  ='Bravissima Livia! 🌈  Ciambelle: '+opts.donuts+'  |  Punteggio: '+opts.score;\n  }else{\n    document.getElementById('ov-icon').textContent ='💔';\n    document.getElementById('ov-title').textContent='Oh no, riprova!';\n    document.getElementById('ov-sub').textContent  ='Forza Livia! Ci riesci! 💪';\n  }\n}\n\nfunction showLevelComplete(){\n  screen='levelcomplete';\n  const texts=[\n    {title:'Livello 1 completato! ⭐',sub:'Bravissima Livia! Pronta per la foresta? 🌲'},\n    {title:'Livello 2 completato! 🌲',sub:'Fantastico! Ora nella città frizzante! 🏙️'},\n  ];\n  const t=texts[Math.min(currentLevel-1,texts.length-1)];\n  document.querySelector('#overlay-lc .ov-title').textContent=t.title;\n  document.querySelector('#overlay-lc .ov-sub').textContent=t.sub;\n  document.getElementById('overlay-lc').style.display='flex';\n  document.getElementById('hud').style.display='none';\n  document.getElementById('controls').style.display='none';\n  stopAll();\n}\n// ─── Options UI ──────────────────────────────────────────────────\nfunction setupOpts(){\n  const D={low:'Meno broccoli, perfetto per iniziare!',high:'Tanti broccoli cattivi – sei pronta?'};\n  document.querySelectorAll('#lives-btns .opts-btn').forEach(b=>{\n    b.addEventListener('click',()=>{\n      optLives=parseInt(b.dataset.val);\n      document.querySelectorAll('#lives-btns .opts-btn').forEach(x=>x.classList.remove('active'));\n      b.classList.add('active');\n    });\n  });\n  document.querySelectorAll('#diff-btns .opts-btn').forEach(b=>{\n    b.addEventListener('click',()=>{\n      optDiff=b.dataset.val;\n      document.querySelectorAll('#diff-btns .opts-btn').forEach(x=>x.classList.remove('active'));\n      b.classList.add('active');\n      document.getElementById('diff-desc').textContent=D[optDiff];\n    });\n  });\n  \n  // Volume sliders\n  const slMusic=document.getElementById('sl-music');\n  const slMusicVal=document.getElementById('sl-music-val');\n  const slSfx=document.getElementById('sl-sfx');\n  const slSfxVal=document.getElementById('sl-sfx-val');\n  slMusic.addEventListener('input',()=>{\n    optMusicVol=parseInt(slMusic.value)/100;\n    slMusicVal.textContent=slMusic.value+'%';\n    audIntro.volume=optMusicVol;\n    audGame.volume=optMusicVol;\n    audForest.volume=optMusicVol;\n  });\n  slSfx.addEventListener('input',()=>{\n    optSfxVol=parseInt(slSfx.value)/100;\n    slSfxVal.textContent=slSfx.value+'%';\n  });\n\n  document.getElementById('opts-back').addEventListener('click',showMenu);\n  document.getElementById('btnOpts').addEventListener('click',showOpts);\n}\n\n// ─── Assets + Splash ─────────────────────────────────────────────\nlet LI={},BR={},Dn={},stImg=null,bgImg=null;\nlet wolfImg=null, fgBgImg=null, fgStImg=null;\nlet cityBgImg=null,cityStageImg=null,caccaImg=null,saliImg=null,cityColl=null;\n\nlet forestColl=null;\nfunction buildForestColl(){\n  if(!fgStImg||!fgStImg.complete||forestColl)return;\n  try{\n    const c=document.createElement('canvas');\n    c.width=fgStImg.naturalWidth||fgStImg.width;\n    c.height=fgStImg.naturalHeight||fgStImg.height;\n    const cx=c.getContext('2d');cx.drawImage(fgStImg,0,0);\n    const d=cx.getImageData(0,0,c.width,c.height);\n    const al=new Uint8Array(c.width*c.height);\n    for(let i=0;i<al.length;i++)al[i]=d.data[i*4+3];\n    forestColl={al,w:c.width,h:c.height};\n    console.log('forestColl:',c.width+'x'+c.height);\n  }catch(e){console.log('forestColl err:',e);}\n}\nfunction isForestSolid(gx,gy){\n  if(!forestColl)return false;\n  if(gy>=H)return true;\n  if(gy<50)return false;\n  const px=Math.round(gx*forestColl.w/LEVEL_W2);\n  const py=Math.round((gy-50)*forestColl.h/STAGE_H2);\n  if(px<0||px>=forestColl.w||py<0||py>=forestColl.h)return false;\n  return forestColl.al[py*forestColl.w+px]>128;\n}\nlet currentLevel=1;\nconst audForest=document.getElementById('aud-forest');\nconst audCity=new Audio(MUSIC_CITY_SRC);audCity.loop=true;audCity.volume=0.5;\nfunction loadAssets(){\n  const entries=[...Object.entries(LIVIA),...Object.entries(BROC),...Object.entries(DN)];\n  let done=0, tot=entries.length+2;\n  const bar=document.getElementById('splash-bar');\n  const lbl=document.getElementById('splash-label');\n  function tick(){\n    done++;\n    bar.style.width=Math.round(done/tot*100)+'%';\n    if(done>=tot){\n      lbl.textContent='Pronti! 🌟';\n      setTimeout(()=>{\n        const spl=document.getElementById('splash');\n        spl.style.transition='opacity 0.5s';spl.style.opacity='0';\n        setTimeout(()=>{spl.style.display='none';showMenu();},500);\n      },300);\n    }\n  }\n  for(const[k,v]of Object.entries(LIVIA)){const i=new Image();i.onload=tick;i.onerror=tick;i.src=v;LI[k]=i;}\n  for(const[k,v]of Object.entries(BROC)) {const i=new Image();i.onload=tick;i.onerror=tick;i.src=v;BR[k]=i;}\n  for(const[k,v]of Object.entries(DN))   {const i=new Image();i.onload=tick;i.onerror=tick;i.src=v;Dn[k]=i;}\n  const si=new Image();si.onload=tick;si.onerror=tick;si.src=STAGE_SRC;stImg=si;\n  const bi=new Image();bi.onload=tick;bi.onerror=tick;bi.src=BG_SRC;bgImg=bi;\n  // Preload level 2 assets (no tick — optional)\n  wolfImg=new Image(); wolfImg.src=WOLF_SHEET_SRC;\n  fgBgImg=new Image(); fgBgImg.src=FOREST_BG_SRC;\n  fgStImg=new Image(); fgStImg.onload=buildForestColl; fgStImg.src=FOREST_STAGE_SRC;\n}\n\n// ─── Platforms ───────────────────────────────────────────────────\nfunction buildPlatformsL2(){\n  let raw=currentLevel===3?RAW_PLATS_L3:currentLevel===2?RAW_PLATS_L2:RAW_PLATS;\n  // L3: filter platforms that overlap with sali travel range (rest pos + full upward travel)\n  if(currentLevel===3){\n    raw=raw.filter(p=>!MOVING_SALI_L3.some(mp=>{\n      const xOvlp=p.x<mp.x+mp.w && p.x+p.w>mp.x;\n      if(!xOvlp)return false;\n      return p.y>=mp.baseY-mp.range-8 && p.y<=mp.baseY+mp.h+10;\n    }));\n  }\n  const sorted=[...raw].sort((a,b)=>a.x-b.x);\n  const list=sorted.map(p=>({...p,h:420-p.y,type:'solid'}));\n  for(let i=0;i<sorted.length-1;i++){\n    const a=sorted[i],b=sorted[i+1];\n    const gap=b.x-(a.x+a.w);\n    if(gap>0&&gap<=40){const by=Math.min(a.y,b.y);list.push({x:a.x+a.w,y:by,w:gap,h:420-by,type:'solid'});}\n  }\n  const lp=sorted[sorted.length-1];\n  list.push({x:lp.x,y:lp.y-24,w:lp.w,h:24,type:'goal'});\n  return list;\n}\nfunction buildPlatformsEx(){\n  const sorted=[...RAW_PLATS].sort((a,b)=>a.x-b.x);\n  const list=sorted.map(p=>({...p,h:H-p.y,type:'solid'}));\n  for(let i=0;i<sorted.length-1;i++){\n    const a=sorted[i],b=sorted[i+1];\n    const gap=b.x-(a.x+a.w);\n    if(gap>0&&gap<=40){const by=Math.min(a.y,b.y);list.push({x:a.x+a.w,y:by,w:gap,h:H-by,type:'solid'});}\n  }\n  const lp=sorted[sorted.length-1];\n  list.push({x:lp.x,y:lp.y-24,w:lp.w,h:24,type:'goal'});\n  return list;\n}\nfunction placeEnemiesEx(platforms){\n  if(currentLevel===3){\n    const wide=platforms.filter(p=>p.type==='solid'&&p.w>=80);\n    const step=optDiff==='high'?1:2;\n    return wide.slice(1).filter((_,i)=>i%step===0).map((p,id)=>({\n      id,x:p.x+p.w*0.4,y:p.y-PH,w:40,h:PH,\n      vx:(optDiff==='high'?1.4+rnd(0.6):1.0+rnd(0.4))*(rnd(1)>0.5?1:-1),\n      sx:p.x+5,range:p.w-10,frame:0,state:'walk',hitTimer:0,dir:1\n    }));\n  }\n  const wide=platforms.filter(p=>p.type==='solid'&&p.w>=80);\n  const step=optDiff==='high'?1:2;\n  return wide.slice(2).filter((_,i)=>i%step===0).map((p,id)=>({\n    id,x:p.x+p.w*0.35,y:p.y-PH,w:40,h:PH,\n    vx:(optDiff==='high'?1.2+rnd(0.8):0.8+rnd(0.5))*(rnd(1)>0.5?1:-1),\n    sx:p.x+5,range:p.w-10,frame:0,state:'walk',hitTimer:0\n  }));\n}\n\n// ─── Drawing ─────────────────────────────────────────────────────\nfunction drawBg(camX){\n  const g=ctx.createLinearGradient(0,0,0,cvs.height);\n  g.addColorStop(0,'#1a0a3e');g.addColorStop(0.5,'#5b2d8e');g.addColorStop(1,'#c084dc');\n  ctx.fillStyle=g;ctx.fillRect(0,0,cvs.width,cvs.height);\n  if(!bgImg||!bgImg.complete)return;\n  ctx.save();ctx.scale(SX,SY);\n  const off=-(camX*0.2)%BG_W;\n  for(let t=-1;t<=Math.ceil(W/BG_W)+1;t++)ctx.drawImage(bgImg,off+t*BG_W,0,BG_W,H);\n  ctx.restore();\n}\nfunction drawStage(camX){\n  if(!stImg||!stImg.complete)return;\n  ctx.save();ctx.scale(SX,SY);ctx.drawImage(stImg,-camX,STAGE_Y,LEVEL_W,STAGE_H);ctx.restore();\n}\nfunction drawBgL2(camX){\n  const g=ctx.createLinearGradient(0,0,0,cvs.height);\n  g.addColorStop(0,'#0a1a0f');g.addColorStop(0.5,'#1a3a1f');g.addColorStop(1,'#2a5a2f');\n  ctx.fillStyle=g;ctx.fillRect(0,0,cvs.width,cvs.height);\n  if(!fgBgImg||!fgBgImg.complete)return;\n  ctx.save();ctx.scale(SX,SY);\n  const off=-(camX*0.2)%BG_W2;\n  for(let t=-1;t<=Math.ceil(W/BG_W2)+1;t++)ctx.drawImage(fgBgImg,off+t*BG_W2,0,BG_W2,H);\n  ctx.restore();\n}\nfunction drawStageL2(camX){\n  if(!fgStImg||!fgStImg.complete)return;\n  ctx.save();ctx.scale(SX,SY);\n  ctx.drawImage(fgStImg,-camX,50,LEVEL_W2,STAGE_H2);\n  ctx.restore();\n}\nfunction drawGoalFlag(p,camX){\n  const px=p.x-camX;if(px<-200||px>W+100)return;\n  ctx.save();ctx.scale(SX,SY);\n  ctx.fillStyle='#9333EA';ctx.fillRect(px+p.w/2-2,p.y-80,4,80);\n  ctx.fillStyle='#EC4899';ctx.beginPath();ctx.moveTo(px+p.w/2+2,p.y-80);ctx.lineTo(px+p.w/2+34,p.y-66);ctx.lineTo(px+p.w/2+2,p.y-52);ctx.fill();\n  ctx.fillStyle='#FDE68A';ctx.font='bold 12px sans-serif';ctx.textAlign='center';\n  ctx.fillText('🏰 META!',px+p.w/2,p.y-12);ctx.textAlign='left';\n  ctx.restore();\n}\nfunction drawDonut(d,camX,frame){\n  if(d.collected)return;const cx=d.x-camX;if(cx<-40||cx>W+40)return;\n  const seq=['rot1','rot2','rot3','rot1','rot5','rot6','rot5','rot4'];\n  const img=Dn[seq[Math.floor(frame*0.15)%seq.length]]||Dn['rot1'];\n  if(!img||!img.complete)return;\n  ctx.save();ctx.scale(SX,SY);ctx.drawImage(img,cx-15,d.y+Math.sin(frame*0.07+d.bob)*3-15,30,30);ctx.restore();\n}\nfunction drawWolf(e,camX){\n  const ex=e.x-camX;if(ex<-120||ex>W+120)return;\n  if(!wolfImg||!wolfImg.complete)return;\n  const frames = e.state==='dead'?WF.dead:e.state==='attack'?WF.attack:WF.walk;\n  const fi = e.state==='attack'\n    ? Math.min(Math.floor(e.frame/15), frames.length-1)  // play once, hold last frame\n    : Math.floor(e.frame/10)%frames.length;              // loop normally\n  const fr = frames[fi];\n  const dh = e.h*1.5, dw = dh*(WF.FW/WF.FH);\n  ctx.save();ctx.scale(SX,SY);\n  if(e.state==='dead'){\n    ctx.globalAlpha=Math.max(0,1-e.frame/55);\n    ctx.drawImage(wolfImg,fr.x,fr.y,WF.FW,WF.FH,ex+e.w/2-dw/2,e.y+e.h-dh,dw,dh);\n    ctx.globalAlpha=1;\n  } else if(e.vx<0){\n    ctx.translate(ex+e.w/2+dw/2,e.y+e.h-dh);ctx.scale(-1,1);\n    ctx.drawImage(wolfImg,fr.x,fr.y,WF.FW,WF.FH,0,0,dw,dh);\n  } else {\n    ctx.drawImage(wolfImg,fr.x,fr.y,WF.FW,WF.FH,ex+e.w/2-dw/2,e.y+e.h-dh,dw,dh);\n  }\n  ctx.restore();\n  e.frame++;\n}\nfunction drawBroc(e,camX){\n  const ex=e.x-camX;if(ex<-100||ex>W+100)return;\n  if(e.state==='dead'){\n    const img=BR['dead'];\n    if(img&&img.complete){\n      const sh=e.h,sw=sh*(img.naturalWidth/img.naturalHeight||1);\n      ctx.save();ctx.scale(SX,SY);ctx.globalAlpha=Math.max(0,1-e.frame/55);\n      ctx.drawImage(img,ex+e.w/2-sw/2,e.y,sw,sh);ctx.globalAlpha=1;ctx.restore();\n    }\n    e.frame++;return;\n  }\n  const wk=['walk1','walk2','walk3','walk4','walk5'];\n  const sp=e.state==='attack'?'attack1':wk[Math.floor(e.frame/8)%wk.length];\n  const img=BR[sp]||BR['walk1'];if(!img||!img.complete){e.frame++;return;}\n  const sh=e.h,sw=sh*(img.naturalWidth/img.naturalHeight||1);\n  ctx.save();ctx.scale(SX,SY);\n  if(e.vx<0){ctx.translate(ex+e.w/2+sw/2,e.y);ctx.scale(-1,1);ctx.drawImage(img,0,0,sw,sh);}\n  else ctx.drawImage(img,ex+e.w/2-sw/2,e.y,sw,sh);\n  ctx.restore();e.frame++;\n}\nfunction drawLivia(pl,camX,frame){\n  if(!pl)return;\n  if(pl.inv>0&&Math.floor(pl.inv/4)%2===0)return;\n  const sp=!pl.onGround?'jump':Math.abs(pl.vx)>0.5?['walk1','walk2','walk3','walk4'][Math.floor(frame/8)%4]:'walk1';\n  const img=LI[sp];if(!img||!img.complete)return;\n  const sh=pl.h,sw=sh*(img.naturalWidth/img.naturalHeight||1);\n  const dx=pl.x-camX+pl.w/2-sw/2,dy=pl.y;\n  ctx.save();ctx.scale(SX,SY);\n  if(pl.facing<0){ctx.translate(dx+sw,dy);ctx.scale(-1,1);ctx.drawImage(img,0,0,sw,sh);}\n  else ctx.drawImage(img,dx,dy,sw,sh);\n  ctx.restore();\n}\nfunction drawParticles(particles,camX){\n  ctx.save();ctx.scale(SX,SY);\n  for(const p of particles){\n    ctx.globalAlpha=p.life/p.maxLife;ctx.fillStyle=p.col;\n    ctx.beginPath();ctx.arc(p.x-camX,p.y,p.r*(p.life/p.maxLife),0,Math.PI*2);ctx.fill();\n  }\n  ctx.globalAlpha=1;ctx.restore();\n}\n// ─── L3 asset loading ──────────────────────────────────────\nfunction loadAssetsL3(){\n  if(!cityBgImg){cityBgImg=new Image();cityBgImg.src=CITY_BG_SRC;}\n  if(!cityStageImg){cityStageImg=new Image();cityStageImg.onload=buildCityColl;cityStageImg.src=CITY_STAGE_SRC;}\n  if(!caccaImg){caccaImg=new Image();caccaImg.src=CACCA_SRC;}\n  if(!saliImg){saliImg=new Image();saliImg.src=SALI_SRC;}\n}\nfunction buildCityColl(){\n  if(!cityStageImg||!cityStageImg.complete||cityColl)return;\n  try{\n    const c=document.createElement('canvas');\n    c.width=cityStageImg.naturalWidth||cityStageImg.width;\n    c.height=cityStageImg.naturalHeight||cityStageImg.height;\n    const cx2=c.getContext('2d');cx2.drawImage(cityStageImg,0,0);\n    const d=cx2.getImageData(0,0,c.width,c.height);\n    const al=new Uint8Array(c.width*c.height);\n    for(let i=0;i<al.length;i++)al[i]=d.data[i*4+3];\n    // Erase sali positions — full travel range (rest to highest) so no ghost floors\n    for(const mp of MOVING_SALI_L3){\n      const py0=Math.max(0,mp.baseY-mp.range-4);  // top of travel\n      const py1=Math.min(c.height,mp.baseY+mp.h+8);  // below rest position\n      const px0=Math.max(0,mp.x),px1=Math.min(c.width,mp.x+mp.w);\n      for(let py2=py0;py2<py1;py2++)for(let px2=px0;px2<px1;px2++)al[py2*c.width+px2]=0;\n    }\n    cityColl={al,w:c.width,h:c.height};\n    console.log('cityColl:',c.width+'x'+c.height);\n  }catch(e){console.log('cityColl err:',e);}\n}\nfunction isCitySolid(gx,gy){\n  if(!cityColl)return false;\n  if(gy<0||gy>=STAGE_H3)return false;\n  const px=Math.round(gx*cityColl.w/LEVEL_W3);\n  const py=Math.round(gy*cityColl.h/STAGE_H3);\n  if(px<0||px>=cityColl.w||py<0||py>=cityColl.h)return false;\n  return cityColl.al[py*cityColl.w+px]>128;\n}\nfunction drawBgL3(camX){\n  const bw=BG_W3;\n  ctx.save();ctx.scale(SX,SY);\n  if(cityBgImg&&cityBgImg.complete){\n    const off=Math.floor(camX*0.3)%bw;\n    // Draw from y=0 to cover full canvas height (avoids pink gap at top)\n    for(let tx=-(off%bw);tx<W+bw;tx+=bw)ctx.drawImage(cityBgImg,tx,0,bw,H);\n  }else{ctx.fillStyle='#87CEEB';ctx.fillRect(0,0,W,H);}\n  ctx.restore();\n}\nfunction drawStageL3(camX){\n  if(!cityStageImg||!cityStageImg.complete)return;\n  if(!cityColl)buildCityColl();\n  ctx.save();ctx.scale(SX,SY);\n  // Punch holes where static sali baked into PNG — only moving sprite version visible\n  ctx.beginPath();\n  ctx.rect(0,0,W,H);\n  for(const mp of MOVING_SALI_L3){\n    const ex=mp.x-camX;\n    if(ex+mp.w>-10&&ex<W+10)ctx.rect(ex,mp.baseY-mp.range-8,mp.w,mp.range+mp.h+16);\n  }\n  ctx.clip('evenodd');\n  const sw=cityStageImg.naturalWidth||cityStageImg.width;\n  const sh=cityStageImg.naturalHeight||cityStageImg.height;\n  ctx.drawImage(cityStageImg,-camX,H-sh,sw,sh);\n  ctx.restore();\n}\nfunction drawSaliPlats(salis,camX){\n  for(const mp of salis){\n    const ex=mp.x-camX;\n    if(ex+mp.w<-10||ex>W+10)continue;\n    ctx.save();ctx.scale(SX,SY);\n    ctx.fillStyle='rgba(0,0,0,0.15)';ctx.fillRect(ex+4,mp.y+mp.h+2,mp.w-8,4);\n    if(saliImg&&saliImg.complete){\n      const sw2=saliImg.naturalWidth||saliImg.width,sh2=saliImg.naturalHeight||saliImg.height;\n      ctx.drawImage(saliImg,0,0,sw2,sh2,ex,mp.y,mp.w,mp.h);\n    }else{ctx.fillStyle='#7a8fa0';ctx.fillRect(ex,mp.y,mp.w,mp.h);}\n    ctx.restore();\n  }\n}\nfunction drawCacca(e,camX){\n  if(!caccaImg||!caccaImg.complete)return;\n  const ex=e.x-camX;\n  if(ex+60<-10||ex>W+10)return;\n  const frames=CACCA_FRAMES[e.state]||CACCA_FRAMES.walk;\n  const fi=e.state==='attack'?Math.min(Math.floor(e.frame/10),frames.length-1):Math.floor(e.frame/8)%frames.length;\n  const fr=frames[fi];\n  const dw=52,dh=68;\n  const fh=(e.state==='dead'||e.state==='attack')?CACCA_FH3:CACCA_FH1;\n  ctx.save();ctx.scale(SX,SY);\n  if(e.dir<0){ctx.translate(ex+dw/2,0);ctx.scale(-1,1);ctx.translate(-(ex+dw/2),0);}\n  ctx.drawImage(caccaImg,fr.x,fr.y,CACCA_FW,fh,ex,e.y-dh+PH,dw,dh);\n  ctx.restore();\n}\nfunction rRect(x,y,w,h,r){\n  ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);\n  ctx.arcTo(x+w,y,x+w,y+r,r);ctx.lineTo(x+w,y+h-r);\n  ctx.arcTo(x+w,y+h,x+w-r,y+h,r);ctx.lineTo(x+r,y+h);\n  ctx.arcTo(x,y+h,x,y+h-r,r);ctx.lineTo(x,y+r);\n  ctx.arcTo(x,y,x+r,y,r);ctx.closePath();\n}\nfunction drawMovingPlats(mps,camX){\n  for(const mp of mps){\n    const ex=mp.x-camX;\n    if(ex+mp.w<-10||ex>W+10)continue;\n    ctx.save();ctx.scale(SX,SY);\n    // Shadow below platform\n    ctx.fillStyle='rgba(0,0,0,0.18)';\n    ctx.fillRect(ex+4,mp.y+mp.h+2,mp.w-8,5);\n    // Platform body — wood/log gradient\n    const grad=ctx.createLinearGradient(ex,mp.y,ex,mp.y+mp.h);\n    grad.addColorStop(0,'#c8a96e');grad.addColorStop(0.45,'#a07840');grad.addColorStop(1,'#6b4f28');\n    ctx.fillStyle=grad;\n    rRect(ex,mp.y,mp.w,mp.h,5);ctx.fill();\n    // Top highlight\n    ctx.fillStyle='rgba(255,230,160,0.4)';\n    rRect(ex+3,mp.y+2,mp.w-6,5,2);ctx.fill();\n    // Wood grain lines\n    ctx.strokeStyle='rgba(80,40,10,0.22)';ctx.lineWidth=1;\n    for(let i=1;i<4;i++){const lx=ex+mp.w*i/4;ctx.beginPath();ctx.moveTo(lx,mp.y+3);ctx.lineTo(lx,mp.y+mp.h-3);ctx.stroke();}\n    ctx.restore();\n  }\n}\nfunction renderFrame(s){\n  ctx.clearRect(0,0,cvs.width,cvs.height);\n  const camX=s?s.camX:0,frame=s?s.frame:0;\n  if(currentLevel===3)drawBgL3(camX);else if(currentLevel===2)drawBgL2(camX);else drawBg(camX);\n  if(currentLevel===3)drawStageL3(camX);else if(currentLevel===2)drawStageL2(camX);else drawStage(camX);\n  if(currentLevel===2&&s&&s.movingPlats)drawMovingPlats(s.movingPlats,camX);\n  if(currentLevel===3&&s&&s.movingPlats)drawSaliPlats(s.movingPlats,camX);\n  if(s){\n    const goal=s.platforms.find(p=>p.type==='goal');\n    if(goal)drawGoalFlag(goal,camX);\n    s.donuts.forEach(d=>drawDonut(d,camX,frame));\n    s.enemies.forEach(e=>currentLevel===3?drawCacca(e,camX):currentLevel===2?drawWolf(e,camX):drawBroc(e,camX));\n    drawParticles(s.particles,camX);\n    if(s.player)drawLivia(s.player,camX,frame);\n  }\n}\n\n// ─── Physics ─────────────────────────────────────────────────────\nfunction hurt(){\n  const s=sRef;if(!s||!s.player||s.player.inv>0)return;\n  s.lives--;lives=s.lives;s.player.inv=130;s.player.vy=-10;sfxHurt();updateHUD();\n  if(s.lives<=0){if(raf){cancelAnimationFrame(raf);raf=null;}showEndScreen('dead');s.player=null;}\n}\nfunction loop(){\n  try{\n  const s=sRef;\n  if(s&&s.player){\n    s.frame++;\n    const{frame,platforms,donuts,enemies,particles,player:pl}=s;\n    // Update moving platforms y position (cosine easing: smooth up-down)\n    if((currentLevel===2||currentLevel===3)&&s.movingPlats){\n      for(const mp of s.movingPlats){\n        const t=(s.frame+mp.phase)%mp.period;\n        mp.prevY=mp.y;\n        // L3 sali move UP (negative direction) from their base position\n        if(currentLevel===3){\n          mp.y=mp.baseY-mp.range/2*(1-Math.cos(2*Math.PI*t/mp.period));\n        }else{\n          mp.y=mp.baseY+mp.range/2*(1-Math.cos(2*Math.PI*t/mp.period));\n        }\n      }\n    }\n    if(K.ArrowLeft)       {pl.vx=-4;pl.facing=-1;}\n    else if(K.ArrowRight) {pl.vx= 4;pl.facing= 1;}\n    else                   pl.vx*=0.80;\n    if(K.ArrowUp&&pl.onGround){pl.vy=-14;pl.onGround=false;sfxJump();}\n    if(pl.onGround&&Math.abs(pl.vx)>0.5)sfxStep(frame);\n    pl.vy=Math.min(pl.vy+0.6,18);\n    const wasOnGround=pl.onGround;pl.x+=pl.vx;pl.y+=pl.vy;pl.onGround=false;\n    if(currentLevel===2){\n      // ── L2: pixel-perfect terrain collision ──\n      if(!forestColl)buildForestColl();\n      // Goal flag (rectangle)\n      for(const p of platforms){\n        if(p.type!=='goal')continue;\n        if(pl.x+pl.w-2>=p.x&&pl.x+2<=p.x+p.w){\n          const pf=pl.y+pl.h-pl.vy,cf=pl.y+pl.h;\n          if(pl.vy>=0&&pf<=p.y+2&&cf>=p.y){\n            if(raf){cancelAnimationFrame(raf);raf=null;}\n            showLevelComplete();s.player=null;return;\n          }\n        }\n      }\n      const feetY=Math.round(pl.y+PH);\n      // MOVING PLATFORM COLLISION (checked before pixel-perfect terrain)\n      if(s.movingPlats){\n        for(const mp of s.movingPlats){\n          {\n            const inX2=pl.x+PW-4>mp.x&&pl.x+4<mp.x+mp.w;\n            if(inX2){\n              const prevRiding2=mp._wasRiding||false;\n              mp._wasRiding=false;\n              if(prevRiding2){\n                pl.y=mp.y-PH;pl.vy=0;pl.onGround=true;mp._wasRiding=true;\n              } else if(pl.vy>=0){\n                const prevFeet=pl.y+PH-pl.vy;\n                if(prevFeet<=mp.y+10&&pl.y+PH>=mp.y-8){\n                  pl.y=mp.y-PH;pl.vy=0;pl.onGround=true;mp._wasRiding=true;\n                }\n              }\n            }\n          }\n        }\n      }\n      // STEP 1: STEP-UP BLOCK — comparative approach.\n      // Compare terrain surface height at the OLD center (before horizontal move)\n      // vs NEW center (after). If terrain rose → undo horizontal move.\n      // This catches ANY rise, including gentle slopes (no dependency on edge pixels).\n      if(wasOnGround&&pl.vy>=0&&Math.abs(pl.vx)>0){\n        const cx_new=Math.round(pl.x+PW/2);\n        const cx_old=Math.round(pl.x-pl.vx+PW/2); // center before this frame's move\n        // Find surface at new center\n        let surf_new=H;\n        if(isForestSolid(cx_new,feetY)){let s=feetY;while(s>50&&isForestSolid(cx_new,s-1))s--;surf_new=s;}\n        // Find surface at old center\n        let surf_old=H;\n        if(isForestSolid(cx_old,feetY)){let s=feetY;while(s>50&&isForestSolid(cx_old,s-1))s--;surf_old=s;}\n        // Block if terrain rose (surf_new < surf_old means terrain got higher on screen)\n        // tolerance=1px for anti-alias noise; only block if there IS terrain ahead (not a gap)\n        if(surf_new<H&&surf_new<surf_old-12){pl.x-=pl.vx;pl.vx=0;}\n      }\n      // STEP 2: GROUND — center-only, stable snap (uses final pl.x after possible undo)\n      const cx2=Math.round(pl.x+PW/2);\n      if(pl.vy>=0&&isForestSolid(cx2,feetY)){\n        let sY=feetY;\n        while(sY>50&&isForestSolid(cx2,sY-1))sY--;\n        pl.y=sY-PH;pl.vy=0;pl.onGround=true;\n      }\n      // STEP 3: CEILING\n      if(pl.vy<0&&isForestSolid(cx2,Math.round(pl.y))){\n        let sY=Math.round(pl.y);\n        while(sY<H&&isForestSolid(cx2,sY+1))sY++;\n        pl.y=sY;pl.vy=0;\n      }\n      // STEP 4: WALL CHECK — always active (upper body pixels catch walls, not terrain surface)\n      {\n        const lx2=Math.round(pl.x+4),rx2=Math.round(pl.x+PW-4);\n        const wmy=Math.round(pl.y+PH*0.55),wty=Math.round(pl.y+PH*0.25);\n        if(pl.vx>0&&(isForestSolid(rx2+1,wmy)&&isForestSolid(rx2+1,wty))){pl.x-=pl.vx;pl.vx=0;}\n        if(pl.vx<0&&(isForestSolid(lx2-1,wmy)&&isForestSolid(lx2-1,wty))){pl.x-=pl.vx;pl.vx=0;}\n      }\n    }else if(currentLevel===3){\n      // ── L3: pixel-perfect city terrain collision (mirrors L2) ──\n      if(!cityColl)buildCityColl();\n      // Goal flag\n      for(const p of platforms){\n        if(p.type!=='goal')continue;\n        if(pl.x+pl.w-2>=p.x&&pl.x+2<=p.x+p.w){\n          const pf=pl.y+pl.h-pl.vy,cf=pl.y+pl.h;\n          if(pl.vy>=0&&pf<=p.y+2&&cf>=p.y){\n            if(raf){cancelAnimationFrame(raf);raf=null;}\n            showEndScreen('win',{donuts:s.donutCount,score:s.score});s.player=null;return;\n          }\n        }\n      }\n      const feetY3=Math.round(pl.y+PH);\n      // Sali (escalator) collision with _saliRiding tracking for smooth up/down carry\n      if(s.movingPlats){\n        const prevRiding=pl._saliRiding||null;\n        pl._saliRiding=null;\n        pl.ridingPlat=null;\n        for(const mp of s.movingPlats){\n          const inX=pl.x+PW-4>mp.x&&pl.x+4<mp.x+mp.w;\n          if(!inX)continue;\n          if(prevRiding===mp){\n            // Player jumped off — release from sali, allow jump\n            if(pl.vy<-2){pl._saliRiding=null;pl.ridingPlat=null;break;}\n            // Was riding last frame: snap to current platform (handles up AND down motion)\n            pl.y=mp.y-PH;pl.vy=0;pl.onGround=true;\n            pl._saliRiding=mp;pl.ridingPlat=mp;\n          } else if(pl.vy>=0){\n            const prevFeet=pl.y+PH-pl.vy;\n            // +10 tolerance so player can walk onto sali at same terrain level\n            if(prevFeet<=mp.y+10&&pl.y+PH>=mp.y-8){\n              pl.y=mp.y-PH;pl.vy=0;pl.onGround=true;\n              pl._saliRiding=mp;pl.ridingPlat=mp;\n            }\n          }\n        }\n      }\n      // Fall-into-void death\n      if(pl.y+PH>STAGE_H3+80){hurt();pl.y=50;pl.vy=0;pl.onGround=false;}\n      // STEP 1: step-up block (same as L2)\n      if(wasOnGround&&pl.vy>=0&&Math.abs(pl.vx)>0){\n        const cx_n=Math.round(pl.x+PW/2),cx_o=Math.round(pl.x-pl.vx+PW/2);\n        let sn=STAGE_H3;if(isCitySolid(cx_n,feetY3)){let s3=feetY3;while(s3>0&&isCitySolid(cx_n,s3-1))s3--;sn=s3;}\n        let so=STAGE_H3;if(isCitySolid(cx_o,feetY3)){let s3=feetY3;while(s3>0&&isCitySolid(cx_o,s3-1))s3--;so=s3;}\n        if(sn<STAGE_H3&&sn<so-12){pl.x-=pl.vx;pl.vx=0;}\n      }\n      // STEP 2: ground snap (skip if riding sali — sali already positioned player)\n      const cx3=Math.round(pl.x+PW/2);\n      if(pl.vy>=0&&!pl.ridingPlat&&isCitySolid(cx3,feetY3)){\n        let sY3=feetY3;while(sY3>0&&isCitySolid(cx3,sY3-1))sY3--;\n        pl.y=sY3-PH;pl.vy=0;pl.onGround=true;\n      }\n      // STEP 3: ceiling\n      if(pl.vy<0&&isCitySolid(cx3,Math.round(pl.y))){\n        let sY3=Math.round(pl.y);while(sY3<STAGE_H3&&isCitySolid(cx3,sY3+1))sY3++;\n        pl.y=sY3;pl.vy=0;\n      }\n      // STEP 4: wall check\n      {\n        const lx3=Math.round(pl.x+4),rx3=Math.round(pl.x+PW-4);\n        const wmy3=Math.round(pl.y+PH*0.55),wty3=Math.round(pl.y+PH*0.25);\n        if(pl.vx>0&&(isCitySolid(rx3+1,wmy3)&&isCitySolid(rx3+1,wty3))){pl.x-=pl.vx;pl.vx=0;}\n        if(pl.vx<0&&(isCitySolid(lx3-1,wmy3)&&isCitySolid(lx3-1,wty3))){pl.x-=pl.vx;pl.vx=0;}\n      }\n      // Cacca enemy logic (mirrors wolf logic from L2)\n      for(const e of enemies){\n        if(e.state==='dead'){\n          if(e.frame<60)e.frame++;\n          else enemies.splice(enemies.indexOf(e),1);\n          continue;\n        }\n        if(e.hitTimer>0){\n          e.hitTimer--;e.frame++;\n          if(e.hitTimer===0)e.state='walk';\n          continue;\n        }\n        // Move\n        e.x+=e.vx;e.frame++;\n        const ex=e.x,ey=e.y+PH;\n        if(isCitySolid(Math.round(ex+20),Math.round(ey+5))||(!isCitySolid(Math.round(ex+20),Math.round(ey+15))&&e.state==='walk')){\n          // Boundary reversal\n        }\n        if(e.x<e.sx||e.x+e.w>e.sx+e.range){e.vx*=-1;e.dir=e.vx>0?1:-1;}\n        e.dir=e.vx>0?1:-1;\n        // Player contact\n        if(pl.inv<=0&&Math.abs(pl.x+PW/2-(e.x+20))<36&&Math.abs(pl.y+PH/2-(e.y+PH/2))<36){\n          if(pl.vy>2&&pl.y+PH<e.y+PH*0.6){\n            e.state='dead';e.frame=0;sfxHit();s.score+=100;s.donutCount++;updateHUD();\n          } else {\n            e.state='attack';e.frame=0;e.hitTimer=45;hurt();\n          }\n        }\n      }\n    }else{\n      // ── L1: rectangle collision ──\n      for(const p of platforms){\n        if(pl.x+pl.w-2<p.x||pl.x+2>p.x+p.w)continue;\n        const prevFeet=pl.y+pl.h-pl.vy,currFeet=pl.y+pl.h;\n        if(pl.vy>=0&&prevFeet<=p.y+2&&currFeet>=p.y){\n          pl.y=p.y-pl.h;pl.vy=0;pl.onGround=true;\n          if(p.type==='goal'){if(raf){cancelAnimationFrame(raf);raf=null;}showLevelComplete();s.player=null;return;}\n        }else if(pl.vy<0&&(pl.y-pl.vy)>=p.y+p.h-2&&pl.y<p.y+p.h){\n          pl.y=p.y+p.h;pl.vy=0;\n        }else if(p.h>40&&pl.y+pl.h>p.y+6&&pl.y<p.y+p.h){\n          if(pl.vx>0&&pl.x+pl.w>p.x&&pl.x+pl.w<p.x+18){pl.x=p.x-pl.w;pl.vx=0;}\n          if(pl.vx<0&&pl.x<p.x+p.w&&pl.x>p.x+p.w-18){pl.x=p.x+p.w;pl.vx=0;}\n        }\n      }\n    }\n    if(pl.y+PH>=(currentLevel===2?H:H+60+PH)){\n      hurt();\n      if(s.player){\n        const safe=[...platforms].filter(p=>p.type==='solid'&&p.x+p.w<=s.camX+W*0.6&&p.w>40).sort((a,b)=>b.x-a.x)[0]||platforms[0];\n        s.player.x=safe.x+safe.w/2-PW/2;s.player.y=safe.y-PH;s.player.vx=0;s.player.vy=0;\n      }\n    }\n    if(s.player){\n      if(pl.x<s.camX+4)pl.x=s.camX+4;\n      s.camX+=(pl.x-W*0.35-s.camX)*0.1;\n      s.camX=Math.max(0,Math.min(s.camX,currentLevel===3?LEVEL_W3-W:LEVEL_W2-W)); if(pl.inv>0)pl.inv--;\n      for(const d of donuts){\n        if(d.collected)continue;\n        const dx=(pl.x+pl.w/2)-d.x,dy=(pl.y+pl.h/2)-d.y;\n        if(Math.sqrt(dx*dx+dy*dy)<26){\n          d.collected=true;s.donutCount++;s.score+=10;donutCount=s.donutCount;score=s.score;sfxDonut();\n          for(let i=0;i<10;i++){const a=rnd(Math.PI*2),sp=1+rnd(3);particles.push({x:d.x,y:d.y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-2,r:4+rnd(4),col:'#FBBF24',life:26,maxLife:26});}\n          updateHUD();\n        }\n      }\n      for(let i=enemies.length-1;i>=0;i--){\n        const e=enemies[i];\n        if(e.state==='dead'){if(e.frame>55)enemies.splice(i,1);continue;}\n        // Wolf update for L2: no gravity, terrain-snap + lookahead-before-move\n        // During attack animation (hitTimer>0): freeze movement, just play frames\n        if(e.hitTimer>0){e.hitTimer--;if(e.hitTimer===0)e.state='walk';continue;}\n        if(currentLevel===2&&forestColl){\n          if(e.y>H+20){enemies.splice(i,1);continue;}\n          const ex2=Math.round(e.x+e.w/2);\n          // Lazy-init: find actual terrain surface on first frame\n          if(!e.L2init){\n            let found=false;\n            for(let sy=Math.max(50,Math.round(e.y));sy<H;sy++){\n              if(isForestSolid(ex2,sy)){\n                let t=sy;while(t>50&&isForestSolid(ex2,t-1))t--;\n                e.y=t-e.h;found=true;break;\n              }\n            }\n            if(!found){enemies.splice(i,1);continue;}\n            e.L2init=true;\n          }\n             // Terrain snap: scan DOWN up to 15px to find surface (handles floating wolves)\n          const efy=Math.round(e.y+e.h);\n          for(let sy=efy;sy<=Math.min(H-1,efy+15);sy++){\n            if(isForestSolid(ex2,sy)){let t=sy;while(t>50&&isForestSolid(ex2,t-1))t--;e.y=t-e.h;break;}\n          }\n          // Lookahead: check terrain 2px ahead AND 5px below feet BEFORE moving\n          // If no ground there → reverse. This prevents gap-walking and oscillation.\n          const nextX=e.x+e.vx;\n          const lookX=Math.round(e.vx>0?nextX+e.w+2:nextX-2);\n          const lookY0=Math.round(e.y+e.h-5),lookY1=Math.round(e.y+e.h+20);\n          const inBounds=nextX>=e.sx&&nextX<=e.sx+e.range;\n          let hasGnd=false;for(let ly=lookY0;ly<=lookY1;ly++){if(isForestSolid(lookX,ly)){hasGnd=true;break;}}\n          if(hasGnd&&inBounds){e.x=nextX;}\n          else{e.vx*=-1;}\n        } else {\n          e.x+=e.vx;if(e.x<e.sx||e.x>e.sx+e.range)e.vx*=-1;\n        }\n        if(e.hitTimer>0){e.hitTimer--;if(e.hitTimer===0)e.state='walk';}\n        if(pl.inv>0)continue;\n        if(pl.x+pl.w-6>e.x&&pl.x+6<e.x+e.w&&pl.y+pl.h-5>e.y&&pl.y+5<e.y+e.h){\n          if(pl.vy>0&&pl.y+pl.h<e.y+e.h*0.4+12){\n            e.state='dead';e.frame=0;pl.vy=-13;s.score+=50;score=s.score;sfxStomp();\n            for(let j=0;j<16;j++){const a=rnd(Math.PI*2),sp=1+rnd(3);particles.push({x:e.x+e.w/2,y:e.y+e.h/2,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-2,r:4+rnd(4),col:'#4ade80',life:32,maxLife:32});}\n            updateHUD();\n          }else{e.state='attack';e.frame=0;e.hitTimer=45;hurt();}\n        }\n      }\n      for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx;p.y+=p.vy;p.vy+=0.15;p.life--;if(p.life<=0)particles.splice(i,1);}\n    }\n  }\n  renderFrame(sRef);\n  }catch(err){console.error('LOOP ERR:',err);}\n  raf=requestAnimationFrame(loop);\n}\n\n// ─── Init game ───────────────────────────────────────────────────\nfunction initGame(level){\n  currentLevel = level || currentLevel;\n  if(raf){cancelAnimationFrame(raf);raf=null;}\n  if(menuRaf){cancelAnimationFrame(menuRaf);menuRaf=null;}\n  const platforms = (currentLevel===2||currentLevel===3) ? buildPlatformsL2() : buildPlatformsEx();\n  const startP=platforms.find(p=>p.type==='solid'&&p.w>100)||platforms[0];\n  lives=optLives;donutCount=0;score=0;\n  sRef={platforms,donuts:placeDonuts(platforms),enemies:placeEnemiesEx(platforms),\n    particles:[],frame:0,camX:0,lives:optLives,score:0,donutCount:0,\n    movingPlats:currentLevel===3?MOVING_SALI_L3.map(mp=>({...mp,y:mp.baseY,prevY:mp.baseY})):currentLevel===2?MOVING_PLATS_L2.map(mp=>({...mp,y:mp.baseY})):[],\n    player:{x:startP.x+startP.w/2-PW/2,y:startP.y-PH,vx:0,vy:0,onGround:false,facing:1,inv:0,w:PW,h:PH}};\n  updateHUD();\n  if(currentLevel===3)loadAssetsL3();\n  document.getElementById('menu').style.display   ='none';\n  document.getElementById('overlay').style.display='none';\n  document.getElementById('hud').style.display    ='flex';\n  document.getElementById('controls').style.display='flex';\n  screen='playing';\n  if(currentLevel===2){\n    playForest();\n    if(!forestColl&&fgStImg&&fgStImg.complete)buildForestColl();\n  }else playGame();\n  loop();\n}\n\n// Level select\nfunction showLevelSelect(){\n  document.getElementById('menu').style.display='none';\n  document.getElementById('lvlsel').style.display='flex';\n}\ndocument.getElementById('lvl1-card').addEventListener('click',()=>{currentLevel=1;document.getElementById('lvlsel').style.display='none';initGame(1);});\ndocument.getElementById('lvl2-card').addEventListener('click',()=>{currentLevel=2;document.getElementById('lvlsel').style.display='none';initGame(2);});\ndocument.getElementById('lvl3-card').addEventListener('click',()=>{currentLevel=3;document.getElementById('lvlsel').style.display='none';initGame(3);});\ndocument.getElementById('lvlsel-back').addEventListener('click',()=>{document.getElementById('lvlsel').style.display='none';showMenu();});\ndocument.getElementById('startBtn').addEventListener('click',showLevelSelect);\ndocument.getElementById('ov-replay').addEventListener('click',()=>initGame(currentLevel));\ndocument.getElementById('ov-menu').addEventListener('click',showMenu);\ndocument.getElementById('lc-continue').addEventListener('click',()=>{\n  document.getElementById('overlay-lc').style.display='none';\n  const nextLvl=currentLevel+1;\n  currentLevel=nextLvl;initGame(nextLvl);\n});\ndocument.getElementById('lc-menu').addEventListener('click',()=>{\n  document.getElementById('overlay-lc').style.display='none';\n  showMenu();\n});\n\n['L','R','J'].forEach(id=>{\n  const el=document.getElementById('btn'+id);\n  const key=id==='L'?'ArrowLeft':id==='R'?'ArrowRight':'ArrowUp';\n  el.addEventListener('pointerdown',()=>K[key]=true);\n  el.addEventListener('pointerup',  ()=>K[key]=false);\n  el.addEventListener('pointerleave',()=>K[key]=false);\n});\ndocument.addEventListener('contextmenu',e=>e.preventDefault());\n\nfunction startMenuAnim(){\n  if(menuRaf)return;\n  (function anim(){\n    if(screen!=='playing'){renderFrame(null);menuRaf=requestAnimationFrame(anim);}\n    else menuRaf=null;\n  })();\n}\n\nsetupOpts();\nloadAssets();\n</script>\n</body>\n</html>";
export default GAME_HTML;
